    "        int a[16];",
    "        for (int i = 0; i < n; i++) a[i] = ds.data[i];",
    "",
    "        comparisons = swaps = maxDepth = 0;",
    "",
    "        quickSort(a, 0, n - 1);",
    "",
    "    }",
    "",
    "    return 0;",
    "}"
